# DK FBV.  Frederiksberg - Vanløse
#
let fv = path("d3.dk.fbv");

with detail = 4, railway = :first :double :pax :removed {
    with link = "line.dk.FBV", layer = -2 {
        track(:station, fv[:fre.yv, :fre.yv + 1seg]);
        track(fv[:fre.yv + 0.99seg, :fre.yn]);
        track(:station, fv[:fre.yn - 0.1dl, :fre.ys]);

        track(:station :single, fv[:fre.ys, :van.yf] << 0.5mo);
        track(:station :single, fv[:fre.ys, :van - 0.5sw] >> 0.5mo);
    }
}


